// ============================================================================
// Red-Black Tree Implementation in C++
// ============================================================================
//
// A Red-Black Tree is a self-balancing Binary Search Tree (BST) with an
// additional bit for each node to indicate its color, either red or black.
// The tree maintains the following properties (Red-Black properties):
//
//   1. Every node is either red or black.
//   2. The root is black.
//   3. All leaves (NIL nodes) are black.
//   4. If a node is red, then both its children are black.
//   5. For each node, all paths from the node to descendant leaves contain
//      the same number of black nodes.
//
// Property 5 is often called the "black-height" property. The black-height
// of a node x is the number of black nodes on any path from x (not including
// x) to a leaf.
//
// These properties ensure that the tree is approximately balanced: the
// longest path can be no more than twice as long as the shortest path.
// This guarantees O(log n) time complexity for search, insert, and delete.
//
// Implementation Details:
//   - We use a singleton NIL node (typically black) to represent null
//     children and leaves. This simplifies the code by avoiding null checks.
//   - The tree is templated on a key type T and a comparator.
//   - We implement insert, erase, find, and additional utility methods.
//   - We include comprehensive unit tests using a simple test framework.
//
// ============================================================================

#include <iostream>
#include <functional>
#include <stdexcept>
#include <string>
#include <vector>
#include <algorithm>
#include <sstream>
#include <cassert>
#include <type_traits>
#include <memory>

// ============================================================================
// Forward Declarations
// ============================================================================

template <typename T, typename Compare = std::less<T>>
class RedBlackTree;

// ============================================================================
// RBNode: Node Structure for the Red-Black Tree
// ============================================================================

/**
 * @brief Node structure for the Red-Black Tree.
 *
 * Each node contains:
 *   - key: The data stored in the node.
 *   - color: Whether the node is RED or BLACK.
 *   - left, right: Pointers to child nodes.
 *   - parent: Pointer to the parent node (used for rotations and fixes).
 *
 * We use a singleton NIL node to represent null children. This is a common
 * technique in Red-Black Tree implementations to simplify the logic.
 */
template <typename T, typename Compare = std::less<T>>
struct RBNode {
    using Self = RBNode<T, Compare>;
    using TreeType = RedBlackTree<T, Compare>;

    enum class Color : uint8_t {
        RED = 0,
        BLACK = 1
    };

    T key;
    Color color;
    Self* left;
    Self* right;
    Self* parent;

    // Constructor for internal nodes
    RBNode(const T& k, Color c, Self* l, Self* r, Self* p)
        : key(k), color(c), left(l), right(r), parent(p) {}

    // Constructor for the NIL sentinel node
    RBNode(Color c)
        : key(T()), color(c), left(nullptr), right(nullptr), parent(nullptr) {}

    // Helper to check if this node is the NIL sentinel
    bool isNil() const {
        // We'll use a flag or compare against a known NIL instance.
        // For simplicity, we'll check if left and right are nullptr and
        // the color is BLACK and key is default-constructed.
        // A more robust approach would be to have a static NIL pointer.
        return false; // Placeholder; we'll handle NIL differently.
    }

    // Swap two nodes (used in erase operations)
    void swapWith(Self* other) {
        std::swap(key, other->key);
        std::swap(color, other->color);
        std::swap(left, other->left);
        std::swap(right, other->right);
        std::swap(parent, other->parent);

        // Update parent pointers of children
        if (left) left->parent = this;
        if (right) right->parent = this;
        if (other->left) other->left->parent = other;
        if (other->right) other->right->parent = other;
    }
};

